const items = $input.all();
const fileListItems = $('Create File List').all();

const output = [];

if (!items.length) {
  throw new Error('No input item found');
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const fileMeta = fileListItems[i]?.json || {};

  let fileContent = '';

  if (item.json.data || item.json.content || item.json.text || item.json.fileContent) {
    fileContent =
      item.json.data ||
      item.json.content ||
      item.json.text ||
      item.json.fileContent;
  } else if (item.binary) {
    const binaryKey = Object.keys(item.binary)[0];

    if (!binaryKey) {
      throw new Error(`Binary file found, but binary key is missing for item ${i}`);
    }

    // n8n binary dosya içeriğini text'e çevirmek için kullanılır
    // @ts-ignore
    const buffer = await this.helpers.getBinaryDataBuffer(i, binaryKey);

    fileContent = buffer.toString('utf8');
  } else {
    throw new Error(`No text or binary file content found for item ${i}`);
  }

  const documentId = item.json.document_id || fileMeta.document_id;
  const title = item.json.title || fileMeta.title;
  const category = item.json.category || fileMeta.category;

  if (!documentId || !title || !category) {
    throw new Error(`Missing metadata for item ${i}. document_id, title or category not found.`);
  }

  const cleaned = fileContent
    .replace(/\r\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  if (!cleaned) {
    throw new Error(`File content is empty after cleaning for document ${documentId}`);
  }

  let chunks = cleaned
    .split(/(?=^##\s+)/m)
    .map(p => p.trim())
    .filter(p => p.length > 0);

  if (chunks.length <= 1) {
    chunks = cleaned
      .split(/\n(?=-\s|\d+\.\s|###\s|##\s)/)
      .map(p => p.trim())
      .filter(p => p.length > 0);
  }

  if (chunks.length <= 1 && cleaned.length > 1000) {
    chunks = [];

    const maxLength = 800;

    for (let start = 0; start < cleaned.length; start += maxLength) {
      const chunk = cleaned.slice(start, start + maxLength).trim();

      if (chunk.length > 0) {
        chunks.push(chunk);
      }
    }
  }

  for (let index = 0; index < chunks.length; index++) {
    output.push({
      json: {
        document_id: documentId,
        title,
        category,
        chunk_index: index,
        content: chunks[index]
      }
    });
  }
}

return output;

const embedding = $json.embeddings?.[0];

if (!embedding) {
  throw new Error('Embedding response not found');
}

const chunk = $('Create Chunks').item.json;

function sqlEscape(value) {
  return String(value ?? '').replace(/'/g, "''");
}

const documentId = chunk.document_id;
const title = chunk.title;
const category = chunk.category;
const chunkIndex = chunk.chunk_index;
const content = chunk.content;
const embeddingVector = `[${embedding.join(',')}]`;

const insertQuery = `
INSERT INTO document_chunks (
  document_id,
  title,
  category,
  chunk_index,
  content,
  embedding
)
VALUES (
  '${sqlEscape(documentId)}',
  '${sqlEscape(title)}',
  '${sqlEscape(category)}',
  ${chunkIndex},
  '${sqlEscape(content)}',
  '${embeddingVector}'::vector
);
`;

return {
  json: {
    document_id: documentId,
    title,
    category,
    chunk_index: chunkIndex,
    content,
    embedding_vector: embeddingVector,
    insert_query: insertQuery
  }
};

